styles:
body {
    font-family: 'Roboto Condensed', sans-serif;
    line-height: 1.6;
    color: #FFFFFF;
    margin: 0;
    padding: 0;
    background-color: #000000;
}
.container {
    max-width: 900px;
    margin: 20px auto;
    padding: 20px 30px;
}
h1, h2, h3, h4 {
    color: #FFFFFF;
    font-weight: 700;
    text-transform: uppercase;
    font-family: 'Roboto Condensed', sans-serif;
}
h1 {
    font-size: 2.5em;
    border-bottom: 3px solid #330000;
    padding-bottom: 15px;
    margin-bottom: 25px;
    text-align: center;
    letter-spacing: 1px;
}
h2 {
    font-size: 1.8em;
    margin-top: 30px;
    border-left: 5px solid #cc0000;
    padding-left: 10px;
}
h3 {
    font-size: 1.3em;
    margin-top: 20px;
    color: #ff3333;
}
h4 {
    font-size: 1.1em;
    margin-top: 15px;
    color: #ffcc00;
}
p {
    margin-bottom: 15px;
    color: #FFFFFF;
}
ul {
    padding-left: 25px;
    margin-bottom: 20px;
}
li {
    margin-bottom: 10px;
    color: #FFFFFF;
}
code {
    background-color: #331a1a;
    padding: 2px 4px;
    border-radius: 3px;
    color: #ffcc00;
}
a {
    color: #ffaa33;
    text-decoration: none;
}
a:hover {
    color: #ffd077;
    text-decoration: underline;
}

/* ----------------------------------------------------------------
   XEM THEM BLOCK
---------------------------------------------------------------- */
div.xem-them {
    display: block;
    box-sizing: border-box;
    width: 100%;
    background-color: #1a1200;
    border-top: 1px solid #7a5500;
    border-right: 1px solid #7a5500;
    border-bottom: 1px solid #7a5500;
    border-left: 4px solid #ffaa33;
    border-radius: 4px;
    padding: 11px 16px;
    margin: 20px 0 24px 0;
    font-family: 'Roboto Condensed', sans-serif;
    font-size: 0.95em;
    font-weight: 700;
    color: #ffaa33;
    letter-spacing: 0.4px;
    text-transform: uppercase;
    line-height: 1.5;
}
div.xem-them a {
    color: #ffcc77;
    text-decoration: none;
    font-weight: 400;
    text-transform: none;
    letter-spacing: 0;
}
div.xem-them a:hover {
    color: #ffe8aa;
    text-decoration: underline;
}

/* --- TABLE --- */
table {
    width: 100%;
    border-collapse: collapse;
    margin: 20px 0;
}
table td, table th {
    border: 1px solid #440000;
    padding: 10px 12px;
    color: #ffffff;
    vertical-align: top;
}
table tr:first-child td {
    background-color: #1a0000;
    font-weight: 700;
    color: #ffcc00;
}
table tr:not(:first-child):nth-child(even) td {
    background-color: #0d0d0d;
}

/* ----------------------------------------------------------------
   HIGHLIGHT BOXES — key point / stat / tip / comparison callouts
---------------------------------------------------------------- */
.callout {
    padding: 14px 18px;
    border-radius: 4px;
    margin: 18px 0;
    font-size: 0.97em;
    line-height: 1.55;
}
.callout .callout-label {
    display: block;
    font-family: 'Roboto Condensed', sans-serif;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.82em;
    letter-spacing: 0.5px;
    margin-bottom: 6px;
}
.callout-key {
    background-color: #1a0000;
    border-left: 4px solid #cc0000;
    color: #f5f5f5;
}
.callout-key .callout-label { color: #ff4d4d; }

.callout-stat {
    background-color: #0d0d0d;
    border-left: 4px solid #ffcc00;
    color: #f5f5f5;
}
.callout-stat .callout-label { color: #ffcc00; }

.callout-tip {
    background-color: #1a1200;
    border-left: 4px solid #ffaa33;
    color: #f5f5f5;
}
.callout-tip .callout-label { color: #ffaa33; }

.callout-compare {
    background-color: #0d0d0d;
    border-left: 4px solid #44aacc;
    color: #f5f5f5;
}
.callout-compare .callout-label { color: #66ccee; }
